// FinPulse — расчёт runway (запаса дней до нуля)
// Вход: строки листа Google Sheets: date | income | expense | comment
// Выход: один item с итогами расчёта

const DAY_MS = 24 * 60 * 60 * 1000;

// Числа из Sheets могут прийти строкой: "150 000", "150000,50", "150 000 ₽"
function toNumber(value, rowInfo) {
  if (value === null || value === undefined || value === '') return 0;
  if (typeof value === 'number') return value;
  const cleaned = String(value).replace(/[^\d,.\-]/g, '').replace(',', '.');
  const n = Number(cleaned);
  // Мусор не превращаем молча в 0: лучше упасть, чем посчитать неверно
  if (!Number.isFinite(n)) throw new Error(`Не число "${value}" в строке: ${rowInfo}`);
  return n;
}

// Даты: ISO "2026-08-01" или русская локаль "01.08.2026"
function toDate(value) {
  const s = String(value).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  if (m) return Date.UTC(+m[3], +m[2] - 1, +m[1]);
  throw new Error(`Не удалось распознать дату: "${value}"`);
}

const fmtDate = ms => new Date(ms).toISOString().slice(0, 10).split('-').reverse().join('.');
const fmtRub = n => Math.round(n).toLocaleString('ru-RU') + ' ₽';

const rows = $input.all()
  .map(item => item.json)
  .filter(r => r.date); // пропускаем пустые строки

if (rows.length === 0) throw new Error('Лист пустой — нечего считать');

let totalIncome = 0;
let totalExpense = 0;
let firstDate = Infinity;
let lastDate = -Infinity;

for (const r of rows) {
  const d = toDate(r.date);
  totalIncome += toNumber(r.income, r.date);
  totalExpense += toNumber(r.expense, r.date);
  firstDate = Math.min(firstDate, d);
  lastDate = Math.max(lastDate, d);
}

// 1. Текущий остаток (стартовый остаток входит в income первой строки)
const balance = totalIncome - totalExpense;

// 2. Средний расход в день: делим на КАЛЕНДАРНЫЕ дни периода, а не на число строк
const periodDays = Math.round((lastDate - firstDate) / DAY_MS) + 1;
const avgDailyExpense = totalExpense / periodDays;

// 3. Runway: на сколько дней хватит остатка при среднем расходе,
//    без учёта будущих поступлений (консервативная оценка)
let runwayDays;
if (balance <= 0) runwayDays = 0;
else if (avgDailyExpense === 0) runwayDays = 9999; // расходов нет — условно «бесконечно»
else runwayDays = Math.floor(balance / avgDailyExpense);

// Дату обнуления считаем от последней записи в логе, а не от даты запуска
const zeroDate = lastDate + runwayDays * DAY_MS;

// Компактный журнал для LLM
const logText = rows
  .map(r => `${r.date} | ${toNumber(r.income, r.date)} | ${toNumber(r.expense, r.date)} | ${r.comment ?? ''}`)
  .join('\n');

return [{
  json: {
    runwayDays,
    balance: Math.round(balance),
    avgDailyExpense: Math.round(avgDailyExpense),
    periodDays,
    dataFrom: fmtDate(firstDate),
    dataTo: fmtDate(lastDate),
    zeroDate: fmtDate(zeroDate),
    balanceText: fmtRub(balance),
    avgDailyExpenseText: fmtRub(avgDailyExpense),
    logText,
  }
}];

